# Generated by build.py from recipe.yml for recipe http-skip-unchanged-files-with-etags. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/a.txt'), "alpha`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/b.txt'), "beta`n")
[IO.File]::WriteAllText((Join-Path $PWD 'sync.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# A sync job: fetches each file only when the server's entity tag differs from the one saved with it.`n# Usage: sh sync.sh <base URL> <file>...`nbase=`$1; shift`nmkdir -p local`nfor f in `"`$@`"; do`n  curl -s -f --etag-compare `"local/`$f.etag`" --etag-save `"local/`$f.etag`" -o `"local/`$f`" -w `"%{http_code} `$f\n`" `"`$base`$f`"`ndone`n")
cmd /c 'touch -t 202401021504.05 site/a.txt site/b.txt'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh sync.sh http://127.0.0.1:8080/ a.txt b.txt } finally { Stop-Process $server0 }
